import {Component,EventEmitter,HostBinding,Input,Output} from '@angular/core';

export interface BreadcrumbItem {
  label: string;
  url?: string;
}

@Component({
  selector: 'brb-breadcrumb',
  standalone: true,
  imports: [],
  templateUrl: './breadcrumb.html',
  styleUrl: './breadcrumb.css',
})
export class Breadcrumb {

  /*INPUTS*/

  @Input() items: BreadcrumbItem[] = [];

  @Input() customClass: string = '';

  @Input() clickable: boolean = true;

  @Input() disabled: boolean = false;


  /*CUSTOM CLASS + STATES*/

  @HostBinding('class')
  get hostClasses(): string {

    return [
      this.customClass,

      this.clickable
        ? 'breadcrumb-clickable'
        : '',

      this.disabled
        ? 'breadcrumb-disabled'
        : ''

    ]
      .filter(Boolean)
      .join(' ');
  }


  /*DEVELOPER EVENT*/

  @Output() clicked =
    new EventEmitter<{
      item: BreadcrumbItem;
      event: MouseEvent;
    }>();


  /* CLICK*/

  onClick(
    item: BreadcrumbItem,
    event: MouseEvent
  ): void {

    if (
      !this.clickable ||
      this.disabled
    ) {
      return;
    }

    this.clicked.emit({
      item,
      event
    });
  }
}

import { Component, ElementRef, EventEmitter, HostBinding, HostListener, Input, Output } from '@angular/core';

export interface DropdownOption {
  label: string;
  value: string;
  disabled?: boolean;
}

@Component({
  selector: 'brb-dropdown',
  standalone: true,
  imports: [],
  templateUrl: './dropdown.html',
  styleUrl: './dropdown.css'
})
export class Dropdown {

  // INPUTS

  @Input() label: string = '';

  @Input() placeholder: string = '';

  @Input() options: DropdownOption[] = [];

  @Input() value: string = '';

  @Input() disabled: boolean = false;

  @Input() searchable: boolean = true;

  @Input()
  @HostBinding('class')
  customClass: string = '';


  // OUTPUTS

  @Output()
  valueChange =
    new EventEmitter<string>();

  @Output()
  selectionChange =
    new EventEmitter<DropdownOption>();

  @Output()
  openedChange =
    new EventEmitter<boolean>();

  @Output()
  clicked =
    new EventEmitter<MouseEvent>();


  // STATE

  isOpen: boolean = false;

  searchText: string = '';


  constructor(
    private elementRef: ElementRef<HTMLElement>
  ) { }


  // FILTERED OPTIONS

  get filteredOptions(): DropdownOption[] {

    const search =
      this.searchText
        .trim()
        .toLowerCase();

    if (!search) {
      return this.options;
    }

    return this.options.filter(
      option =>
        option.label
          .toLowerCase()
          .includes(search)
    );
  }


  // SELECTED OPTION

  get selectedOption():
    DropdownOption | undefined {

    return this.options.find(
      option =>
        option.value === this.value
    );
  }


  // TOGGLE

  toggleDropdown(
    event?: MouseEvent
  ): void {

    if (this.disabled) {
      return;
    }

    if (event) {
      this.clicked.emit(event);
    }

    this.isOpen =
      !this.isOpen;

    this.openedChange.emit(
      this.isOpen
    );

    if (!this.isOpen) {
      this.searchText = '';
    }
  }


  // DOCUMENT CLICK

  @HostListener(
    'document:click',
    ['$event']
  )
  onDocumentClick(
    event: MouseEvent
  ): void {

    if (!this.isOpen) {
      return;
    }

    const target =
      event.target as Node;

    const host =
      this.elementRef.nativeElement;

    if (!host.contains(target)) {
      this.closeDropdown();
    }
  }


  // CLOSE

  closeDropdown(): void {

    if (!this.isOpen) {
      return;
    }

    this.isOpen = false;

    this.searchText = '';

    this.openedChange.emit(false);
  }


  // SELECT

  selectOption(
    option: DropdownOption,
    event: MouseEvent
  ): void {

    if (option.disabled) {
      return;
    }

    this.value =
      option.value;

    this.valueChange.emit(
      option.value
    );

    this.selectionChange.emit(
      option
    );

    this.clicked.emit(event);

    this.isOpen = false;

    this.searchText = '';

    this.openedChange.emit(false);
  }


  // SEARCH

  onSearch(event: Event): void {

    const input =
      event.target as HTMLInputElement;

    this.searchText =
      input.value;
  }
}

import {Component,Input,Output,EventEmitter,HostBinding,HostListener,ElementRef} from '@angular/core';

export interface MultiSelectOption {
  label: string;
  value: string;
  disabled?: boolean;
}

@Component({
  selector: 'brb-multi-select-dropdown',
  standalone: true,
  imports: [],
  templateUrl: './multi-select-dropdown.html',
  styleUrl: './multi-select-dropdown.css',
})
export class MultiSelectDropdown {

  // INPUTS

  @Input() label: string = 'Add Parameters';

  @Input() options: MultiSelectOption[] = [];

  @Input() selectedValues: string[] = [];

  @Input() placeholder: string = 'Select options';

  /*
   * TRUE  = show checkbox
   * FALSE = hide checkbox
   */
  @Input() useCheckbox: boolean = true;

  @Input() customClass: string = '';

  @Input() clickable: boolean = true;

  @Input() disabled: boolean = false;


  // STATE

  isOpen: boolean = false;


  // HOST CLASSES

  @HostBinding('class')
  get hostClasses(): string {

    return [
      this.customClass,

      this.clickable
        ? 'dropdown-clickable'
        : '',

      this.disabled
        ? 'dropdown-disabled'
        : '',

      this.isOpen
        ? 'dropdown-open'
        : ''

    ]
      .filter(Boolean)
      .join(' ');
  }


  // EVENTS

  @Output()
  selectionChange =
    new EventEmitter<string[]>();

  @Output()
  opened =
    new EventEmitter<void>();

  @Output()
  closed =
    new EventEmitter<void>();

  @Output()
  clicked =
    new EventEmitter<MouseEvent>();


  // CONSTRUCTOR

  constructor(
    private elementRef: ElementRef
  ) {}


  // TOGGLE

  toggle(event: MouseEvent): void {

    if (
      this.disabled ||
      !this.clickable
    ) {
      return;
    }

    event.stopPropagation();

    this.clicked.emit(event);

    this.isOpen = !this.isOpen;

    if (this.isOpen) {

      this.opened.emit();

    } else {

      this.closed.emit();

    }
  }


  // OPTION CLICK

  onOptionClick(
    option: MultiSelectOption,
    event: MouseEvent
  ): void {

    if (
      this.disabled ||
      option.disabled ||
      !this.clickable
    ) {
      return;
    }

    event.stopPropagation();

    const values =
      [...this.selectedValues];

    const index =
      values.indexOf(option.value);


    // ADD
    if (index === -1) {

      values.push(option.value);

    }

    // REMOVE
    else {

      values.splice(index, 1);

    }


    this.selectedValues =
      values;


    this.selectionChange.emit(
      [...values]
    );
  }


  // CHECK SELECTED

  isSelected(
    option: MultiSelectOption
  ): boolean {

    return this.selectedValues
      .includes(option.value);
  }


  // DISPLAY TEXT

  get displayText(): string {

    return this.label;
  }


  // OUTSIDE CLICK

  @HostListener(
    'document:click',
    ['$event']
  )
  onDocumentClick(
    event: MouseEvent
  ): void {

    if (!this.isOpen) {
      return;
    }

    const target =
      event.target as Node;

    if (
      !this.elementRef
        .nativeElement
        .contains(target)
    ) {

      this.close();
    }
  }


  // CLOSE

  close(): void {

    if (!this.isOpen) {
      return;
    }

    this.isOpen = false;

    this.closed.emit();
  }
}

import { Component, ElementRef, EventEmitter, HostBinding, HostListener, Input, Output } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { MatIconModule } from '@angular/material/icon';
export interface NavLink {
  label: string;
  url: string;
}

export interface UserProfile {
  name: any;
  username: string;
  email: string;
  image?: string;
  role?: string;
  initials?: string;
}
@Component({
  selector: 'brb-navbar',
  standalone: true,
  imports: [CommonModule, RouterModule, MatIconModule],
  templateUrl: './navbar.html',
  styleUrl: './navbar.css',
})
export class Navbar {

  // Brand
  @Input() brand = '';

  @Input() logoAlt = '';

  @Input() image = '';

  @Input() customClass = '';

  @HostBinding('class')
  // Navigation
  @Input() links: NavLink[] = [];

  // Authentication
  @Input() initiallyLoggedIn = false;

  // User profile
  @Input() user!: UserProfile;

  // Icons
  @Input() notificationIcon = '';

  @Input() profileIcon = '';

  @Input() userIcon = '';

  @Input() logoutIcon = '';

  // Events
  @Output() login = new EventEmitter<void>();

  @Output() logout = new EventEmitter<void>();

  isLoggedIn = false;
  isDropdownOpen = false;

  constructor(private elementRef: ElementRef) { }

  ngOnInit(): void {
    this.isLoggedIn = this.initiallyLoggedIn;
  }

  handleLoginClick(): void {
    this.isLoggedIn = true;
    this.login.emit();
  }

  handleProfileClick(): void {
    this.isDropdownOpen = !this.isDropdownOpen;
  }

  handleLogoutClick(): void {
    this.isLoggedIn = false;
    this.isDropdownOpen = false;
    this.logout.emit();
  }

  @HostListener('document:mousedown', ['$event'])
  onDocumentClick(event: MouseEvent): void {

    if (
      this.isDropdownOpen &&
      !this.elementRef.nativeElement.contains(event.target)
    ) {
      this.isDropdownOpen = false;
    }
  }
}

