/*BREADCRUMB HOST*/

:host {

  /*SIZE */

  --breadcrumb-width: 100%;

  --breadcrumb-min-height: 40px;


  /*SPACING*/

  --breadcrumb-gap: 12px;

  --breadcrumb-padding: 0;


  /*COLORS*/

  --breadcrumb-color: #111111;

  --breadcrumb-current-color: #111111;

  --breadcrumb-hover-color: #3478f6;

  --breadcrumb-arrow-color: #777777;


  /*TEXT*/

  --breadcrumb-font-size: 26px;

  --breadcrumb-font-weight: 600;

  --breadcrumb-current-font-weight: 700;

  --breadcrumb-line-height: 1.3;


  /*ARROW*/

  --breadcrumb-arrow-size: 30px;

  --breadcrumb-arrow-weight: 400;


  /*FONT*/

  --breadcrumb-font-family:
    Arial,
    Helvetica,
    sans-serif;


  /*HOST*/

  display: block;

  width: var(--breadcrumb-width);

  min-height: var(--breadcrumb-min-height);

  box-sizing: border-box;
}


/*MAIN BREADCRUMB*/

.balina-breadcrumb {

  width: 100%;

  min-height:
    var(--breadcrumb-min-height);

  box-sizing: border-box;

  display: flex;

  align-items: center;

  flex-wrap: wrap;

  gap:
    var(--breadcrumb-gap);

  padding:
    var(--breadcrumb-padding);

  color:
    var(--breadcrumb-color);

  font-family:
    var(--breadcrumb-font-family);

  font-size:
    var(--breadcrumb-font-size);

  font-weight:
    var(--breadcrumb-font-weight);

  line-height:
    var(--breadcrumb-line-height);
}


/*BREADCRUMB ITEM*/

.breadcrumb-item {

  display: flex;

  align-items: center;

  gap:
    var(--breadcrumb-gap);

  flex: 0 0 auto;

  white-space: nowrap;
}


/*LABEL*/

.breadcrumb-label {

  display: inline-flex;

  align-items: center;

  color:
    var(--breadcrumb-color);

  font-size:
    var(--breadcrumb-font-size);

  font-weight:
    var(--breadcrumb-font-weight);

  line-height:
    var(--breadcrumb-line-height);

  cursor: pointer;

  user-select: none;

  transition:
    color 0.2s ease,
    opacity 0.2s ease;
}


/*CURRENT PAGE*/

.breadcrumb-current {

  color:
    var(--breadcrumb-current-color);

  font-weight:
    var(--breadcrumb-current-font-weight);

  cursor: default;
}


/*HOVER*/

:host(.breadcrumb-clickable)
.breadcrumb-label:not(.breadcrumb-current):hover {

  color:
    var(--breadcrumb-hover-color);

  opacity: 0.8;
}


/*ARROW*/

.breadcrumb-arrow {

  display: flex;

  align-items: center;

  justify-content: center;

  flex: 0 0 auto;

  color:
    var(--breadcrumb-arrow-color);

  font-size:
    var(--breadcrumb-arrow-size);

  font-weight:
    var(--breadcrumb-arrow-weight);

  line-height: 1;

  user-select: none;
}


/*NOT CLICKABLE*/

:host(:not(.breadcrumb-clickable))
.breadcrumb-label {

  cursor: default;
}


/*DISABLED*/

:host(.breadcrumb-disabled) {

  opacity: 0.55;

  pointer-events: none;

  cursor: not-allowed;
}


/*RESPONSIVE - TABLET*/

@media (max-width: 768px) {

  :host {

    --breadcrumb-font-size: 21px;

    --breadcrumb-arrow-size: 27px;

    --breadcrumb-gap: 9px;

    --breadcrumb-min-height: 36px;
  }
}


/*RESPONSIVE - MOBILE*/

@media (max-width: 480px) {

  :host {

    --breadcrumb-font-size: 18px;

    --breadcrumb-arrow-size: 24px;

    --breadcrumb-gap: 7px;

    --breadcrumb-min-height: 32px;
  }


  .balina-breadcrumb {

    flex-wrap: nowrap;

    overflow-x: auto;

    overflow-y: hidden;

    scrollbar-width: thin;
  }


  .breadcrumb-item {

    flex-shrink: 0;
  }
}


/*SMALL MOBILE*/

@media (max-width: 360px) {

  :host {

    --breadcrumb-font-size: 16px;

    --breadcrumb-arrow-size: 21px;

    --breadcrumb-gap: 5px;
  }
}

