/*
   BALINA BUTTON HOST
*/

:host {

  /* =========================================
     DESIGN TOKENS
  ========================================= */

  /* SIZE */

  --button-width: auto;

  --button-min-width: 0;

  --button-height: 44px;

  --button-min-height: 44px;

  --button-padding: 0 22px;


  /* COLORS */

  --button-background: #68479b;

  --button-background-hover: #593b84;

  --button-background-active: #4b326f;

  --button-text-color: #ffffff;

  --button-border: 1px solid #68479b;


  /* BORDER */

  --button-radius: 6px;


  /* FONT */

  --button-font-family:
    Arial,
    Helvetica,
    sans-serif;

  --button-font-size: 14px;

  --button-font-weight: 600;


  /* FLEX */

  --button-gap: 8px;

  --button-justify-content: center;

  --button-align-items: center;


  /* EFFECTS */

  --button-shadow:
    0 2px 5px
    rgba(0, 0, 0, 0.08);

  --button-focus-ring:
    rgba(104, 71, 155, 0.2);


  /* DISABLED */

  --button-disabled-background: #dddddd;

  --button-disabled-text: #999999;

  --button-disabled-border: #dddddd;


  /* SPINNER */

  --button-spinner-size: 16px;

  --button-spinner-border: 2px;


  /* =========================================
     HOST FLEX
  ========================================= */

  display: inline-flex;

  flex: 0 1 auto;

  width: var(--button-width);

  min-width: var(--button-min-width);

  max-width: 100%;

  box-sizing: border-box;

  font-family:
    var(--button-font-family);
}


/*
   =========================================
   BUTTON
   =========================================
*/

.balina-button {

  width: 100%;

  min-width: 0;

  min-height:
    var(--button-min-height);

  height:
    var(--button-height);

  padding:
    var(--button-padding);


  /* FLEX */

  display: flex;

  flex-direction: row;

  align-items:
    var(--button-align-items);

  justify-content:
    var(--button-justify-content);

  gap:
    var(--button-gap);


  /* BOX */

  box-sizing: border-box;

  border:
    var(--button-border);

  border-radius:
    var(--button-radius);


  /* COLORS */

  background:
    var(--button-background);

  color:
    var(--button-text-color);


  /* FONT */

  font-family:
    var(--button-font-family);

  font-size:
    var(--button-font-size);

  font-weight:
    var(--button-font-weight);

  line-height: 1.2;


  /* INTERACTION */

  box-shadow:
    var(--button-shadow);

  outline: none;

  cursor: pointer;

  user-select: none;


  /* IMPORTANT FOR FLEX */

  overflow: hidden;

  transition:
    background-color 0.2s ease,
    border-color 0.2s ease,
    box-shadow 0.2s ease,
    transform 0.1s ease,
    color 0.2s ease;
}


/*
   =========================================
   CLICKABLE STATE
   =========================================
*/

:host(.button-clickable)
.balina-button {

  cursor: pointer;
}


/*
   =========================================
   NOT CLICKABLE
   =========================================
*/

:host(:not(.button-clickable))
.balina-button {

  cursor: default;
}


/*
   =========================================
   HOVER
   =========================================
*/

:host(.button-clickable)
.balina-button:hover {

  background:
    var(--button-background-hover);
}


/*
   =========================================
   ACTIVE
   =========================================
*/

:host(.button-clickable)
.balina-button:active {

  background:
    var(--button-background-active);

  transform:
    translateY(1px);
}


/*
   =========================================
   FOCUS
   =========================================
*/

.balina-button:focus-visible {

  box-shadow:
    0 0 0 3px
    var(--button-focus-ring);
}


/*
   =========================================
   DISABLED
   =========================================
*/

:host(.button-disabled)
.balina-button {

  background:
    var(--button-disabled-background);

  color:
    var(--button-disabled-text);

  border-color:
    var(--button-disabled-border);

  cursor: not-allowed;

  pointer-events: none;

  box-shadow: none;

  transform: none;
}


/*
   =========================================
   LOADING
   =========================================
*/

.balina-button[aria-busy='true'] {

  cursor: wait;
}


/*
   =========================================
   LABEL
   =========================================
