/* OPTION */

:host .dropdown-option {

  width: 100%;

  min-width: 0;

  height:
    var(--dropdown-option-height);

  min-height:
    var(--dropdown-option-height);

  flex: 0 0 auto;

  display: flex;

  flex-direction: row;

  align-items: center;

  padding:
    var(--dropdown-option-padding);

  box-sizing: border-box;

  border: none;

  border-radius: 6px;

  background: transparent;

  color:
    var(--dropdown-option-text);

  font-family: inherit;

  font-size:
    var(--dropdown-option-size);

  font-weight:
    var(--dropdown-option-weight);

  text-align: left;

  cursor: pointer;

  outline: none;

  transition:
    background 0.12s ease,
    color 0.12s ease;
}


/* OPTION HOVER */

:host .dropdown-option:hover {

  background:
    var(--dropdown-hover);
}


/* SELECTED OPTION */

:host .dropdown-option.option-selected {

  background:
    var(--dropdown-selected);

  color: #2457d6;
}


/* SELECTED HOVER */

:host .dropdown-option.option-selected:hover {

  background: #e2e9ff;
}


/* CHECKBOX */

:host .checkbox {

  width:
    var(--dropdown-checkbox-size);

  height:
    var(--dropdown-checkbox-size);

  min-width:
    var(--dropdown-checkbox-size);

  min-height:
    var(--dropdown-checkbox-size);

  flex: 0 0
    var(--dropdown-checkbox-size);

  display: flex;

  align-items: center;

  justify-content: center;

  margin-right:
    var(--dropdown-checkbox-gap);

  box-sizing: border-box;

  background:
    var(--dropdown-background);

  border:
    1.5px solid
    var(--dropdown-border);

  border-radius:
    var(--dropdown-checkbox-radius);

  transition:
    background 0.12s ease,
    border-color 0.12s ease;
}


/* CHECKED CHECKBOX */

:host .checkbox.checkbox-selected {

  background:
    var(--dropdown-focus-border);

  border-color:
    var(--dropdown-focus-border);
}


/* CHECKMARK */

:host .checkmark {

  color: #ffffff;

  font-size: 12px;

  font-weight: 700;

  line-height: 1;
}


/* OPTION LABEL */

:host .option-label {

  flex: 1 1 auto;

  min-width: 0;

  overflow: hidden;

  white-space: nowrap;

  text-overflow: ellipsis;
}


/* DISABLED OPTION */

:host .dropdown-option.option-disabled {

  opacity: 0.45;

  cursor: not-allowed;
}


:host .dropdown-option.option-disabled:hover {

  background: transparent;
}


/* SCROLLBAR */

:host .dropdown-options::-webkit-scrollbar {

  width: 5px;
}


:host .dropdown-options::-webkit-scrollbar-track {

  background: transparent;

  margin: 5px 0;
}


:host .dropdown-options::-webkit-scrollbar-thumb {

  background:
    var(--dropdown-scrollbar);

  border-radius: 10px;

  min-height: 35px;
}


:host .dropdown-options::-webkit-scrollbar-thumb:hover {

  background: #5c3bb0;
}


/* FIREFOX SCROLLBAR */

:host .dropdown-options {

  scrollbar-width: thin;

  scrollbar-color:
    var(--dropdown-scrollbar)
    transparent;
}


/* DISABLED COMPONENT */

:host(.dropdown-disabled) {

  opacity: 0.55;

  pointer-events: none;
}


/* RESPONSIVE TABLET */

@media (max-width: 768px) {

  :host {

    --dropdown-width: 280px;

    --dropdown-header-height: 42px;

    --dropdown-option-height: 38px;
  }
}


/* RESPONSIVE MOBILE */

@media (max-width: 480px) {

  :host {

    --dropdown-width: 100%;

    --dropdown-header-height: 42px;

    --dropdown-header-padding: 0 11px;

    --dropdown-label-size: 14px;

