  display: flex;

  align-items: center;

  box-sizing: border-box;
}

/*
   INPUT WRAPPER
 */

.text-box-input-wrapper {
  position: relative;

  width: 100%;

  height: 100%;

  display: flex;

  align-items: center;

  box-sizing: border-box;
}

/*
   INPUT
 */

.text-box-input {
  width: 100%;

  height: 100%;

  box-sizing: border-box;

  padding: var(--textbox-padding);

  border: var(--textbox-border);

  border-radius: var(--textbox-radius);

  outline: none;

  background: var(--textbox-background);

  color: var(--textbox-text-color);

  font-family: var(--textbox-font-family);

  font-size: var(--textbox-font-size);

  font-weight: var(--textbox-font-weight);

  transition:
    border-color 0.2s ease,
    box-shadow 0.2s ease,
    background-color 0.2s ease;

  cursor: text;
}

/*
   PASSWORD INPUT
 */

.text-box-input[type='password'] {
  padding-right: 48px;
}

/*
   PLACEHOLDER
 */

.text-box-input::placeholder {
  color: var(--textbox-placeholder-color);

  opacity: 1;

  font-family: var(--textbox-font-family);

  font-size: var(--textbox-font-size);

  font-weight: var(--textbox-font-weight);
}

/*
   HOVER
 */

.text-box-input:hover:not(:disabled) {
  border-color: var(--textbox-border-hover);
}

/*
   FOCUS
 */

.text-box-input:focus {
  border-color: var(--textbox-border-focus);

  box-shadow: var(--textbox-focus-shadow);
}

/*
   DISABLED
 */

.text-box-input:disabled {
  background: var(--textbox-disabled-background);

  color: var(--textbox-disabled-color);

  border-color: var(--textbox-disabled-border);

  cursor: not-allowed;
}

/*
   READONLY
 */

.text-box-input:read-only {
  cursor: default;
}

/*
   PASSWORD BUTTON
 */

.text-box-password-button {
  position: absolute;

  right: 8px;

  top: 50%;

  transform: translateY(-50%);

  width: 32px;

  height: 32px;

  display: flex;

  align-items: center;

  justify-content: center;

  padding: 0;

  border: none;

  background: transparent;

  color: var(--textbox-icon-color);

  cursor: pointer;

  border-radius: 4px;

  transition:
    color 0.2s ease,
    background-color 0.2s ease;
}

/*
   PASSWORD BUTTON HOVER
 */

.text-box-password-button:hover:not(:disabled) {
  color: var(--textbox-icon-hover-color);

  background: rgba(0, 0, 0, 0.05);
