/*
   BALINA TIME FILTER
 */

:host {
  /*
     BALINA UI DESIGN TOKENS
 */

  --time-filter-gap: 16px;

  --time-filter-circle-size: 24px;

  --time-filter-circle-border-width: 2px;

  --time-filter-dot-size: 12px;

  --time-filter-border-color: #a6a6a6;

  --time-filter-selected-color: #1976d2;

  --time-filter-text-color: #000000;

  --time-filter-text-hover: #333333;

  --time-filter-font-family: Arial, Helvetica, sans-serif;

  --time-filter-font-size: 20px;

  --time-filter-font-weight: 400;

  --time-filter-disabled-color: #aaaaaa;

  /*
     CONTAINER
 */

}

:host .time-filter {

  display: flex;

  align-items: center;

  gap: var(--time-filter-gap);

  width: fit-content;

  box-sizing: border-box;

  font-family: var(--time-filter-font-family);

  user-select: none;

  transition: opacity 0.2s ease;
}

/*
   CLICKABLE
 */

:host(.time-filter-clickable) .time-filter {
  cursor: pointer;
}

/*
   RADIO CIRCLE
 */

:host .radio-circle {
  width: var(--time-filter-circle-size);

  height: var(--time-filter-circle-size);

  flex-shrink: 0;

  display: flex;

  align-items: center;

  justify-content: center;

  box-sizing: border-box;

  border: var(--time-filter-circle-border-width) solid var(--time-filter-border-color);

  border-radius: 50%;

  transition:
    border-color 0.2s ease,
    background-color 0.2s ease;
}

/*
   RADIO DOT
 */

:host .radio-dot {
  width: var(--time-filter-dot-size);

  height: var(--time-filter-dot-size);

  border-radius: 50%;

  background: transparent;

  transition:
    background-color 0.2s ease,
    transform 0.2s ease;
}

/*
   SELECTED
 */

:host .radio-circle.selected {
  border-color: var(--time-filter-selected-color);
}

:host .radio-circle.selected .radio-dot {
  background: var(--time-filter-selected-color);

  transform: scale(1);
}

/*
   LABEL
 */

:host .label {
  color: var(--time-filter-text-color);

  font-size: var(--time-filter-font-size);

  font-weight: var(--time-filter-font-weight);

  line-height: 1;

  transition: color 0.2s ease;
}

/*
   HOVER
 */

:host(.time-filter-clickable) .time-filter:hover .label {
  color: var(--time-filter-text-hover);
}

/*
   SELECTED HOVER
 */

:host(.time-filter-clickable) .time-filter:hover .radio-circle {
  border-color: var(--time-filter-selected-color);
}

/*
   DISABLED
 */

:host(.time-filter-disabled) .time-filter {
  opacity: 0.6;

  cursor: not-allowed;
}

:host(.time-filter-disabled) .time-filter .radio-circle {
  border-color: var(--time-filter-disabled-color);
}

:host(.time-filter-disabled) .time-filter .label {
  color: var(--time-filter-disabled-color);
}

/*
   DISABLED SELECTED
 */

:host(.time-filter-disabled) .time-filter .radio-circle.selected {
  border-color: var(--time-filter-disabled-color);
}

:host(.time-filter-disabled) .time-filter .radio-circle.selected .radio-dot {
  background: var(--time-filter-disabled-color);
}

/*
   RESPONSIVE
 */

@media (max-width: 768px) {
  :host .time-filter {
    --time-filter-font-size: 18px;

    --time-filter-circle-size: 22px;

    --time-filter-dot-size: 10px;

    --time-filter-gap: 12px;
  }
}

@media (max-width: 480px) {
  :host .time-filter {
    --time-filter-font-size: 16px;

    --time-filter-circle-size: 20px;

    --time-filter-dot-size: 9px;

    --time-filter-gap: 10px;
  }
}

